<?php
declare(strict_types=1);
require_once __DIR__.'/config.php';
function db(): PDO {
 static $pdo=null;
 if($pdo) return $pdo;
 $config=db_config();
 if(empty($config['name']) || empty($config['user'])) throw new RuntimeException('Die Datenbank ist nicht konfiguriert. Bitte DB_NAME und DB_USER in .env eintragen.');
 $dsn=sprintf('mysql:host=%s;port=%s;dbname=%s;charset=%s',$config['host'],$config['port'],$config['name'],$config['charset']);
 $pdo=new PDO($dsn,$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
 return $pdo;
}
function e(?string $s): string { return htmlspecialchars($s ?? '', ENT_QUOTES, 'UTF-8'); }
function base_url(): string { $p=rtrim(dirname($_SERVER['SCRIPT_NAME'] ?? ''),'/\\'); return $p==='.'?'':$p; }
function site_url(string $path=''): string { return base_url().($path ? '/'.ltrim($path,'/') : ''); }
function asset(string $path): string { return site_url($path); }
function redirect(string $url): never { header('Location: '.$url); exit; }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(24)); return $_SESSION['csrf']; }
function check_csrf(): void { if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')) { http_response_code(400); exit('Ungültige Anfrage.'); } }
function logged_in(): bool { return !empty($_SESSION['admin_id']); }
function require_login(): void { if(!logged_in()) redirect(site_url('admin/login.php')); }
function flash(?string $set=null): ?string { if($set!==null){$_SESSION['flash']=$set; return null;} $v=$_SESSION['flash']??null; unset($_SESSION['flash']); return $v; }
function init_db(): void {
 $pdo=db();
 $pdo->exec("CREATE TABLE IF NOT EXISTS admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at VARCHAR(64) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
