 $pdo->exec("CREATE TABLE IF NOT EXISTS awards(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, year VARCHAR(20) NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, image VARCHAR(500), url VARCHAR(500), published TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
