 $pages=[
 ['home','Startseite','MEDIEN. KULTUR. ZUKUNFT.','Junge Menschen machen Medien.','Young Images verbindet Filmbildung, kulturelle Bildung und Medienbildung. Wir ermöglichen jungen Menschen, ihre Ideen zu entwickeln, kreativ umzusetzen und mit anderen zu teilen.','assets/images/about.jpg'],
