 if((int)$pdo->query('SELECT COUNT(*) FROM offers')->fetchColumn()===0){$ins=$pdo->prepare('INSERT INTO offers(title,category,target,duration,short_text,body,image,contact,published,sort_order) VALUES(?,?,?,?,?,?,?,?,1,?)');$data=[['Medienworkshop Schule','SCHULE','3.–6. Klasse','1–5 Projekttage','Film, Video und Medien praktisch kennenlernen.','Wir planen Workshops passend zu Alter, Thema und Rahmenbedingungen der Schule.','assets/images/field-film.jpg','Young Images'],['Medienworkshop Freizeit','FREIZEIT','Kinder & Jugendliche','1–3 Tage','Kreativ produzieren und gemeinsam Spaß haben.','Ferien, Jugendhaus oder Gruppe: Wir bringen Methoden und Technik mit und entwickeln gemeinsam ein passendes Format.','assets/images/project-mediensommer.jpg','Young Images'],['Fort- und Weiterbildung','FORTBILDUNG','Pädagogische Fachkräfte','nach Absprache','Medienpädagogik praxisnah und direkt einsetzbar.','Fortbildungen zu Film, Medienbildung, KI und medienpädagogischer Praxis – individuell für Teams und Einrichtungen.','assets/images/field-media.jpg','Young Images'],['Medienpädagogische Beratung','BERATUNG','Pädagogische Einrichtungen','nach Absprache','Von der Idee bis zur Umsetzung.','Wir beraten und begleiten Einrichtungen bei medienpädagogischen Konzepten, Projekten und Entwicklungsprozessen.','assets/images/about.jpg','Young Images']];foreach($data as $i=>$r)$ins->execute([...$r,$i]);}
