 if((int)$pdo->query('SELECT COUNT(*) FROM funders')->fetchColumn()===0){$ins=$pdo->prepare('INSERT INTO funders(name,description,logo,url,published,sort_order) VALUES(?,?,?,?,1,?)');$names=['Aktion Mensch','Medienanstalt Berlin-Brandenburg','Landespräventionsrat Brandenburg','MBJS – Ministerium für Bildung, Jugend und Sport Brandenburg','Mein Land – Meine Zukunft','Kultur macht Stark','Plattform Kulturelle Bildung Brandenburg – Kulturland Brandenburg','Brandenburgische Landeszentrale für Politische Bildung','Stiftung Toleranz (FC Flick Stiftung)'];foreach($names as $i=>$n)$ins->execute([$n,'Förderer von Young Images.','',$n==='Aktion Mensch'?'https://www.aktion-mensch.de':'',$i]);}
