function q(string $sql,array $params=[]): array {$st=db()->prepare($sql);$st->execute($params);return $st->fetchAll(PDO::FETCH_ASSOC);}
function one(string $sql,array $params=[]): ?array {$r=q($sql,$params);return $r[0]??null;}
function setting(string $key): string { $r=one('SELECT * FROM settings WHERE id=1'); return (string)($r[$key]??''); }
function save_upload(string $field): ?string { if(empty($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return null; $f=$_FILES[$field]; if($f['error']!==UPLOAD_ERR_OK||$f['size']>MAX_UPLOAD)throw new RuntimeException('Upload fehlgeschlagen oder Datei zu groß.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif','application/pdf'=>'pdf']; if(!isset($allowed[$mime]))throw new RuntimeException('Nur JPG, PNG, WEBP, GIF oder PDF sind erlaubt.'); if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0755,true); $name=date('Ymd_His').'_'.bin2hex(random_bytes(4)).'.'.$allowed[$mime]; move_uploaded_file($f['tmp_name'],UPLOAD_DIR.$name); return 'uploads/'.$name; }
function page_by_slug(string $slug): array { return one('SELECT * FROM pages WHERE slug=? AND published=1',[$slug]) ?? []; }
